package ex0413;

public class Ex06foreach {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//for each문 : 배열, 리스트의 요소를 하나씩 반복하는 반복문
		//python에서 list = [1,2,3,4] 
		
		
		//for each
		int [] arr1 = {10,20,30}; //배열
		for (int num1 : arr1) {
			//3번 반복 
			System.out.println(num1);
		}
	}

}
